\title{A Quadratically-Faster Midpoint Acceleration of the
Euler--Mascheroni Constant}
\author{Aristotle}
\date{June 26, 2026}

\begin{document}

\begin{abstract}
The Euler--Mascheroni constant $\gamma = \lim_{n\to\infty}(H_n - \ln n)$ is
classically bracketed by two sequences with \emph{linear} convergence: the lower
approximant $a_n = H_n - \ln(n+1)$, increasing to $\gamma$ from below, and the
upper approximant $b_n = H_n - \ln n$, decreasing to $\gamma$ from above; both
have error $\Theta(1/n)$. We introduce the \emph{midpoint approximant}
$m_n = H_n - \ln\!\left(n + \tfrac12\right)$, obtained by sampling the logarithm
at the midpoint of the unit step rather than at either endpoint. We prove that
$m_n$ is strictly decreasing, converges to $\gamma$, and bounds $\gamma$ strictly
from above ($\gamma < m_n$ for all $n$), yielding the new two-sided sandwich
$a_n < \gamma < m_n$. The decisive analytic input is the elementary
$\artanh$ inequality $2t < \ln\frac{1+t}{1-t}$ for $t\in(0,1)$, equivalent to
strict convexity of $1/x$ (Hermite--Hadamard). Numerically the new bound
overshoots by $m_n - \gamma \approx 1/(24\,n^2)$, a quadratic acceleration over
the classical endpoints. All results have been formally verified.
\end{abstract}

\maketitle

\section{Introduction}

The harmonic numbers $H_n = \sum_{k=1}^{n} 1/k$ diverge logarithmically, and
their deviation from $\ln n$ converges to the \emph{Euler--Mascheroni constant}
\[
\gamma = \lim_{n\to\infty}\bigl(H_n - \ln n\bigr) = 0.5772156649\ldots
\]
This constant pervades analytic number theory (the average order of the divisor
function, the Mertens theorems, the Laurent expansion of $\zeta$ at $s=1$), the
analysis of algorithms, and the theory of special functions (it equals
$-\Gamma'(1)$). Whether $\gamma$ is rational or irrational is a famous open
problem, so sharp two-sided enclosures of $\gamma$ are of standing interest.

Two standard sequences enclose $\gamma$: $a_n = H_n - \ln(n+1)$ increases to
$\gamma$ from below, and $b_n = H_n - \ln n$ decreases to $\gamma$ from above, so
$a_n < \gamma < b_n$. Both converge only linearly: $b_n - \gamma \sim 1/(2n)$.
The two approximants differ only in where the logarithm is sampled---the right
endpoint $n+1$ or the left endpoint $n$ of a unit interval. We sample at the
\emph{midpoint} $n+\tfrac12$ and prove the resulting sequence is a strictly
decreasing upper approximant with the same per-term cost but quadratically
smaller error.

\section{Definitions}

\begin{definition}[Harmonic numbers]
$H_n = \sum_{k=1}^{n} \frac{1}{k}$, with $H_0 = 0$.
\end{definition}

\begin{definition}[Midpoint approximant; \texttt{midpointSeq}]
For $n \in \N$, \[ m_n = H_n - \ln\!\left(n + \tfrac12\right). \]
\end{definition}

For comparison we use $a_n = H_n - \ln(n+1)$ and $b_n = H_n - \ln n$, and
$\gamma = \lim_n a_n$, with the established facts $a_n \uparrow \gamma$,
$b_n \downarrow \gamma$, and $a_n < \gamma < b_n$.

\section{The engine inequality}

\begin{lemma}[\texttt{two\_mul\_lt\_log\_div}]\label{lem:artanh}
For every $t \in (0,1)$,
\[ 2t < \ln\!\left(\frac{1+t}{1-t}\right). \]
\end{lemma}

\begin{proof}[Proof sketch]
Let $f(x) = \ln(1+x) - \ln(1-x) - 2x$ on $[0,t]$. Then $f(0)=0$ and
\[
f'(x) = \frac{1}{1+x} + \frac{1}{1-x} - 2 = \frac{2x^2}{1-x^2} > 0
\qquad (x \in (0,t)).
\]
By the Mean Value Theorem there is $c \in (0,t)$ with $f(t) = f(t)-f(0) =
f'(c)\,t > 0$, i.e. $2t < \ln(1+t)-\ln(1-t) = \ln\frac{1+t}{1-t}$.
\end{proof}

The right-hand side equals $2\artanh(t) = 2t + \tfrac23 t^3 + \tfrac25 t^5 +
\cdots$; the lemma is the positivity of the cubic-and-higher tail, the analytic
shadow of strict convexity of $x \mapsto 1/x$.

\section{Monotonicity}

\begin{lemma}[Per-step decrease; \texttt{midpoint\_step}]\label{lem:step}
For every $n \in \N$,
\[ \frac{1}{n+1} < \ln\!\left(n+\tfrac32\right) - \ln\!\left(n+\tfrac12\right). \]
\end{lemma}

\begin{proof}[Proof sketch]
Set $t = \frac{1}{2n+2} \in (0,1)$. Then
$\frac{1+t}{1-t} = \frac{2n+3}{2n+1} = \frac{n+3/2}{n+1/2}$, so the right side of
Lemma~\ref{lem:artanh} equals $\ln(n+\tfrac32) - \ln(n+\tfrac12)$ while its left
side is $2t = 1/(n+1)$. Apply Lemma~\ref{lem:artanh}.
\end{proof}

Equivalently, Hermite--Hadamard for the convex function $1/x$ on
$[n+\tfrac12, n+\tfrac32]$ (midpoint $n+1$) gives
$\ln(n+\tfrac32) - \ln(n+\tfrac12) = \int_{n+1/2}^{n+3/2} \frac{dx}{x} >
\frac{1}{n+1}$.

\begin{theorem}[Strict monotonicity; \texttt{strictAnti\_midpointSeq}]\label{thm:anti}
The sequence $(m_n)_{n\in\N}$ is strictly decreasing.
\end{theorem}

\begin{proof}[Proof sketch]
Using $H_{n+1} = H_n + \frac{1}{n+1}$,
\[
m_{n+1} - m_n = \frac{1}{n+1} - \bigl[\ln(n+\tfrac32) - \ln(n+\tfrac12)\bigr] < 0
\]
by Lemma~\ref{lem:step}.
\end{proof}

\section{Convergence and the main bound}

\begin{theorem}[Convergence; \texttt{tendsto\_midpointSeq}]\label{thm:conv}
$\displaystyle \lim_{n\to\infty} m_n = \gamma.$
\end{theorem}

\begin{proof}[Proof sketch]
For $n \ge 1$, $\ln n \le \ln(n+\tfrac12) \le \ln(n+1)$, so
$a_n \le m_n \le b_n$. Since $a_n \to \gamma$ and $b_n \to \gamma$, the squeeze
theorem gives $m_n \to \gamma$.
\end{proof}

\begin{theorem}[Main result; \texttt{eulerMascheroniConstant\_lt\_midpointSeq}]\label{thm:main}
For every $n \in \N$, \[ \gamma < m_n. \]
\end{theorem}

\begin{proof}[Proof sketch]
By Theorem~\ref{thm:anti}, $m_k \le m_{n+1}$ for all $k \ge n+1$; letting
$k\to\infty$ and using Theorem~\ref{thm:conv} gives $\gamma \le m_{n+1}$.
Since $m_{n+1} < m_n$, we conclude $\gamma < m_n$.
\end{proof}

\begin{remark}
The bound $\gamma < m_n$ does \emph{not} follow from the classical
$\gamma < b_n$: comparison with $b_n$ gives only $m_n < b_n$. The from-above
guarantee genuinely requires the monotone-limit argument.
\end{remark}

\section{The improved sandwich}

\begin{theorem}[Improvement over lower approximant;
\texttt{eulerMascheroniSeq\_lt\_midpointSeq}]\label{thm:beats}
For every $n \in \N$, \[ a_n = H_n - \ln(n+1) < H_n - \ln\!\left(n+\tfrac12\right) = m_n. \]
\end{theorem}

\begin{proof}[Proof sketch]
$n+\tfrac12 < n+1$ and $\ln$ is strictly increasing, so
$\ln(n+\tfrac12) < \ln(n+1)$; subtracting from $H_n$ reverses the inequality.
\end{proof}

\begin{theorem}[New two-sided sandwich; \texttt{midpointSeq\_sandwich}]\label{thm:sandwich}
For every $n \in \N$,
\[
H_n - \ln(n+1) < \gamma < H_n - \ln\!\left(n+\tfrac12\right).
\]
\end{theorem}

\begin{proof}[Proof sketch]
The left inequality is the classical $a_n < \gamma$; the right inequality is
Theorem~\ref{thm:main}.
\end{proof}

The sandwich is strictly tighter on the upper side: the upper edge moves from
$b_n = H_n - \ln n$ down to $m_n = H_n - \ln(n+\tfrac12)$, while remaining a valid
upper bound on $\gamma$.

\section{Quantitative rate (numerical)}

The proved results establish sign and monotonicity; the rate is an empirical
observation. With $t_n = \frac{1}{2n+2}$, the decrement is
\[
d_n = m_n - m_{n+1} = 2\artanh(t_n) - 2t_n = \tfrac23 t_n^3 + \tfrac25 t_n^5 + \cdots
= \Theta(1/n^3),
\]
so $m_n - \gamma = \sum_{k\ge n} d_k = \Theta(1/n^2)$ with leading constant
$1/24$: $m_n - \gamma \sim \frac{1}{24\,n^2}$.

\begin{center}
\begin{tabular}{rrrr}
\toprule
$n$ & $m_n - \gamma$ & $n^2(m_n-\gamma)$ & $b_n - \gamma$ \\
\midrule
1   & 0.01731923 & 0.017319 & 0.422784 \\
2   & 0.00649360 & 0.025974 & 0.229637 \\
5   & 0.00136958 & 0.034239 & 0.096680 \\
10  & 0.00037733 & 0.037733 & 0.049167 \\
20  & 0.00009911 & 0.039642 & 0.024792 \\
50  & 0.00001634 & 0.040843 & 0.009967 \\
100 & 0.00000413 & 0.041252 & 0.004992 \\
200 & 0.00000104 & 0.041459 & 0.002498 \\
\bottomrule
\end{tabular}
\end{center}

The column $n^2(m_n-\gamma)$ converges to $1/24 = 0.041\overline{6}$, confirming
the quadratic law and its constant, while $b_n - \gamma \sim 1/(2n)$ confirms the
classical linear rate.

\section{Algorithms}

\paragraph{Rigorous enclosure.}
Given $\varepsilon>0$, increase $n$ until the certified width
$m_n - a_n = \ln(n+1) - \ln(n+\tfrac12) = \Theta(1/n)$ drops below
$\varepsilon$; return $[a_n, m_n] \ni \gamma$ (Theorem~\ref{thm:sandwich}).

\paragraph{Quadratic point estimate.}
To estimate $\gamma$ to tolerance $\tau$, take $n \approx \sqrt{1/(24\tau)}$ and
return $m_n$; this needs $O(1/\sqrt{\tau})$ harmonic terms versus $O(1/\tau)$ for
$b_n$.

\section{Discussion and future work}

The linear error of the one-sided approximants is odd about the midpoint of the
unit step and therefore cancels, exposing the even term $1/(24 n^2)$. This
suggests three sharpenings.

\begin{conjecture}[Explicit quadratic bound]
For all $n \ge 1$, $m_n - \gamma \le 1/(12 n^2)$, with sharp asymptotic constant
$1/24$, via a telescoping domination
$d_k \le \tfrac{1}{12}\bigl(1/k^2 - 1/(k+1)^2\bigr)$.
\end{conjecture}

\begin{conjecture}[Optimal shift uniqueness]
For $s_c(n) = H_n - \ln(n+c)$, $\,n\,(s_c(n)-\gamma) \to (\tfrac12 - c)$, so
$s_c(n)-\gamma = o(1/n)$ iff $c = \tfrac12$.
\end{conjecture}

\begin{conjecture}[Quartic accelerator]
$H_n - \ln\!\left(n + \tfrac12 + \tfrac{1}{24 n}\right)$ converges to $\gamma$
with error $O(1/n^4)$.
\end{conjecture}

\section{Conclusion}

Sampling the logarithm at the midpoint of the unit step makes
$m_n = H_n - \ln(n+\tfrac12)$ a strictly decreasing, provably-from-above estimate
of $\gamma$, with the improved sandwich
$H_n - \ln(n+1) < \gamma < H_n - \ln(n+\tfrac12)$. The cost matches the classical
bound, yet the error falls from $\Theta(1/n)$ to $\Theta(1/n^2)$ with leading
constant $1/24$. The proof rests on the single elementary inequality
$2t < \ln\frac{1+t}{1-t}$, the analytic face of the convexity of $1/x$.

