"""Verify the main theorem: the two-sided sandwich a_n < gamma < m_n."""
from __future__ import annotations
import math

GAMMA: float = 0.57721566490153286060651209008240243104215933593992


def harmonic(n: int) -> float:
    """n-th harmonic number H_n = sum_{k=1}^n 1/k."""
    return sum(1.0 / k for k in range(1, n + 1))


def lower_approximant(n: int) -> float:
    """Classical lower approximant a_n = H_n - ln(n+1)."""
    return harmonic(n) - math.log(n + 1.0)


def midpoint_approximant(n: int) -> float:
    """Midpoint approximant m_n = H_n - ln(n + 1/2)."""
    return harmonic(n) - math.log(n + 0.5)


def verify_sandwich(ns: list[int]) -> None:
    """Check a_n < gamma < m_n at each n (midpointSeq_sandwich)."""
    print(f"{'n':>5} {'a_n':>16} {'gamma':>16} {'m_n':>16} {'ok':>5}")
    for n in ns:
        a, m = lower_approximant(n), midpoint_approximant(n)
        print(f"{n:>5} {a:>16.12f} {GAMMA:>16.12f} {m:>16.12f} {str(a < GAMMA < m):>5}")


if __name__ == "__main__":
    verify_sandwich([1, 2, 5, 10, 50, 100, 1000, 10000])

"""Demonstrate the quadratic acceleration m_n - gamma ~ 1/(24 n^2)."""
from __future__ import annotations
import math

GAMMA: float = 0.57721566490153286060651209008240243104215933593992


def harmonic(n: int) -> float:
    """n-th harmonic number."""
    return sum(1.0 / k for k in range(1, n + 1))


def midpoint_error(n: int) -> float:
    """m_n - gamma where m_n = H_n - ln(n+1/2)."""
    return (harmonic(n) - math.log(n + 0.5)) - GAMMA


def classical_upper_error(n: int) -> float:
    """b_n - gamma where b_n = H_n - ln n."""
    return (harmonic(n) - math.log(n)) - GAMMA


def compare_rates(ns: list[int]) -> None:
    """Tabulate n^2*(m_n-gamma) -> 1/24 vs 2n*(b_n-gamma) -> 1/2."""
    print(f"{'n':>6} {'m_n-g':>16} {'n^2*(m_n-g)':>14} {'2n*(b_n-g)':>12}")
    for n in ns:
        em, eb = midpoint_error(n), classical_upper_error(n)
        print(f"{n:>6} {em:>16.12f} {n*n*em:>14.6f} {2*n*eb:>12.6f}")
    print(f"target midpoint constant 1/24 = {1/24:.6f}; classical 1/2 = 0.5")


if __name__ == "__main__":
    compare_rates([1, 2, 5, 10, 20, 50, 100, 500, 1000, 5000])
